import { useState, useRef } from 'react'
import type { ReactNode } from 'react'

import { Box, Container, Collapsible, VStack, HStack, useBreakpointValue } from '@chakra-ui/react'

import { BsArrowDownCircle } from 'react-icons/bs'

import { MyYesButton } from '~/ui/parts/MyButton'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'



type SectionCardProp = {
  title: ReactNode;
  prelude: ReactNode;
  children: ReactNode;
}
export function SectionCard(prop: SectionCardProp) {
  const { title, prelude, children } = prop;
  const isTriggerContext = useBreakpointValue<boolean>({ smDown: false, sm: true }, { ssr: false }) || false;
  
  const [openPrelude, setOpenPrelude] = useState<boolean>(false);
  const preludeTriggerRef = useRef<HTMLButtonElement | null>(null);
  const handlerClickPrelude = () => setOpenPrelude((curOpen) => {
    if (!curOpen) {
      preludeTriggerRef.current?.focus({ preventScroll: true });
    }
    return true;
  });
  
  return (
    <Container as='section' shadow='md' css={styles.container}>
      {/* 親の::beforeで背景画像をセットすると、position: fixedとかだと裏に隠れて見えなくなる。relativeとしてそこからグループを始めることで解消。 */}
      <HStack className='header'>
        <Box as='h4' className='title'>{title}</Box>
        {/* buttonのサイズはchakra-uiデフォルトのrem指定で、collapseHeightもそれに併せる。後々button共々emへ修正するかも */}
        <Collapsible.Root className='prelude-area' collapsedHeight='2.25rem' display='flex'
          open={openPrelude} onOpenChange={(e) => setOpenPrelude(e.open)}
          >
          <Collapsible.Trigger asChild>
            <MyYesButton className='prelude-toggled' size='sm' ref={preludeTriggerRef}>
              {isTriggerContext && (
                <Collapsible.Context>
                  {(api) => (api.open ? '折りたたむ' : '続きを読む')}
                </Collapsible.Context>
              )}
              <Collapsible.Indicator
                transition='transform 0.2s'
                _open={{ transform: 'rotate(180deg)' }}
                >
                <BsArrowDownCircle />
              </Collapsible.Indicator>
            </MyYesButton>
          </Collapsible.Trigger>
          <Collapsible.Content
            className='prelude'
            _closed={{
              shadow: 'inset 0 -12px 12px -12px var(--shadow-color)',
              shadowColor: 'blackAlpha.500',
            }}
            onClick={handlerClickPrelude}
            >
            {prelude}
          </Collapsible.Content>
        </Collapsible.Root>
      </HStack>
      <VStack w='100%'>
        {children}
      </VStack>
    </Container>
  )
}

const styles = {
  container: css`
    position: relative;
    margin-bottom: 0.5em;
    width: 100%;
    padding-inline: 5px; 
    
    /* filterは以降の子要素全てに適応されてしまうため、::beforeに適応 */
    &::before {
      content: "";
      position: absolute;
      inset: 0;
      background-image: url('${import.meta.env.BASE_URL}/substrate_v.jpg');
      background-repeat: repeat repeat;
      filter: brightness(0.95);
    }
    > .header {
      background-image: url('${import.meta.env.BASE_URL}/substrate_h.jpg');
      background-repeat: repeat repeat;
      margin: 0.5em 0 1em 0;
      position: relative;
      align-items: start;
      margin-inline: -5px;
      padding-inline: 5px;
      
      > .title {
        word-break: keep-all;
        /* button, collapseHeightに併せてrem指定。後で共々emへ直すかも */
        height: 2.25rem;
        line-height: 2.25rem;
        
        text-shadow: 0 0 1px white, 0 0 2px aliceblue;
        font-weight: 800;
        background: rgb(250 250 200 / 0.7);
        border-radius: 0.25em;
        padding-inline: 0.25em;
        //box-shadow: 1px 1px 2px rgb(0 0 0 / 0.5);
      }
      > .prelude-area {
        --intro-border-width: 2px;
        border-top: var(--intro-border-width) solid rgb(0 0 0 / 0.3);
        border-right: var(--intro-border-width) solid rgb(255 255 255 / 0.3);
        border-radius: 0.25em 0.25em 0.25em 0;
        > .prelude-toggled {
          margin-top: calc(var(--intro-border-width) * -0.5);
          margin-right: calc(var(--intro-border-width) * -0.25);
        }
        > .prelude {
          border-bottom: var(--intro-border-width) solid rgb(255 255 255 / 0.3);
          border-left: var(--intro-border-width) solid rgb(0 0 0 / 0.2);
          padding-left: 0.25em;
          border-radius: 0 0 0.25em 0.25em;
          background: rgb(255 255 200 / 0.5);
        }
      }
    }
  `
}
