import type { ReactNode } from 'react'

import { VStack } from '@chakra-ui/react'

import { MyScrollArea } from '~/ui/parts/MyScrollArea'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'

type Prop = {
  children: ReactNode
}
export function MyMainArea(prop: Prop) {
  const { children } = prop;
  
  return (
    <MyScrollArea.Normal css={styles.main.root}>
      <VStack css={styles.main.content} w='100%' padding='0.5rem 0'>
        {children}
      </VStack>
    </MyScrollArea.Normal>
  )
}

export function MyMethodMainArea(prop: Prop) {
  const { children } = prop;
  
  return (
    <MyScrollArea.Normal padding='5px 0'>
      <VStack css={styles.method.content} w='100%'>
        {children}
      </VStack>
    </MyScrollArea.Normal>
  )
}



const styles = {
  main: {
    root: css`
      background: white;
    `,
    content: css`
      position: relative;
      &::before {
        content: "";
        position: absolute;
        inset: 0;
        background-image: url('${import.meta.env.BASE_URL}/substrate_v.jpg');
        background-repeat: repeat repeat;
        filter: brightness(0.9);
      }
    `
  },
  method: {
    content: css`
      position: relative;
      &::before {
        content: "";
        position: absolute;
        inset: 0;
        background-image: url('${import.meta.env.BASE_URL}/substrate_v.jpg');
        background-repeat: repeat repeat;
        filter: brightness(0.9);
      }
    `
  }
} as const


